import { axiosExpressHandler } from "./AxiosInstance"

export async function InterfaceWithChatBot(message:String){
    try{
        const response = await axiosExpressHandler.get("/python-service/"+ message);
        return response.data;
    }catch(error){
        console.error("Error fetching data: ", error);
        throw error;
    }
}
